namespace datagraph.data.graph.panel.model.row;

using ghidra.program.model.listing;

/**
 * Abstract class for displaying rows in a Data GTrable model. Each row maintains its indent level 
 * and whether or not is is expanded. GTables are like tables, but with a tree like structure. Each
 * row that is a child of another row has its indent level set to one more than its parent. The 
 * expanded flag is used to indicate if a given row has visible child rows showing or not.
 */

public abstract class DataRowObject {
	private int indentLevel;
	private bool isExpanded;

	/**
	 * Constructor
	 * @param indentLevel the indent level for this row object
	 * @param isExpanded true if this object has child rows that are being displayed
	 */
	protected DataRowObject(int indentLevel, bool isExpanded) {
		this.indentLevel = indentLevel;
		this.isExpanded = isExpanded;
	}

	public int getIndentLevel() {
		return indentLevel;
	}

	public bool isExpanded() {
		return isExpanded;
	}

	/**
	 * {@return the name for this row. Typically this will be the field name, but it could be 
	 * a descriptive title for a group such as array range.}
	 */
	public abstract string getName();

	/**
	 * {@return the interpreted value for the data at this location.}
	 */
	public abstract string getValue();

	/**
	 * {@return the name of the datatype at this location.}
	 */
	public abstract string getDataType();

	/**
	 * {@return true if the row can produce child rows.}
	 */
	public abstract bool isExpandable();

	/**
	 * {@return true if this location represents a pointer or has outgoing references}
	 */
	public bool hasOutgoingReferences() {
		return false;
	}

	/**
	 * {@return the Data object associated with this row.}
	 */
	public abstract Data getData();

}
